<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Заметки — ТРПО 06</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f5fa;color:#172033;font:16px system-ui}header{background:#172554;color:white;padding:24px max(20px,calc((100% - 900px)/2))}main{max-width:900px;margin:28px auto;padding:0 18px}.panel{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:20px;margin-bottom:18px}input{padding:10px;border:1px solid #cbd5e1;border-radius:8px;font:inherit;max-width:100%}button{background:#315efb;color:white;border:0;border-radius:8px;padding:10px 14px;font:inherit;cursor:pointer}.note{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #e2e8f0}.done{text-decoration:line-through;color:#64748b}.muted{color:#64748b}.error,.success{padding:10px;border-radius:8px}.error{background:#fee2e2;color:#991b1b}.success{background:#dcfce7;color:#166534}@media(max-width:600px){.note{align-items:flex-start;flex-direction:column}}
</style></head><body><header><h1>Мои учебные заметки</h1>Практическая работа №06 · JSON и сессии</header><main><p class="muted">Солопов Антон · ЭПБО-01-25</p>
<section class="panel"><h2>Состояние сессии</h2><p>Пользователь: <strong><?=e($data['displayName'])?></strong></p><form method="post"><input type="hidden" name="action" value="name"><input name="display_name" maxlength="60" placeholder="Ваше имя"><button>Сохранить имя</button></form><form method="post" style="margin-top:10px"><input type="hidden" name="action" value="clear"><button>Сбросить сессию</button></form></section>
<section class="panel"><h2>Добавить заметку</h2><form method="post"><input type="hidden" name="action" value="add"><input name="title" maxlength="180" required placeholder="Текст заметки"><button>Добавить</button></form><?php if($data['error']):?><p class="error"><?=e($data['error'])?></p><?php endif;?><?php if($data['message']):?><p class="success"><?=e($data['message'])?></p><?php endif;?></section>
<section class="panel"><h2>Список заметок</h2><?php foreach($data['notes'] as $n):?><div class="note"><span class="<?=$n['done']?'done':''?>"><?=e($n['title'])?></span><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button><?=$n['done']?'Вернуть':'Выполнено'?></button></form></div><?php endforeach;?><?php if(!$data['notes']):?><p class="muted">Заметок пока нет.</p><?php endif;?></section></main></body></html>